require __DIR__.'/includes/bootstrap.php';require_login();require_member($pdo);$memberId=current_member_id();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';try{
 if($a==='add_panel'){$name=trim($_POST['name']??'');$count=max(1,min(72,(int)($_POST['module_count']??12)));if($name==='')throw new RuntimeException('Completează denumirea panoului.');$s=$pdo->prepare('INSERT INTO house_electrical_panels(name,location,module_count,notes,created_by_member_id) VALUES(?,?,?,?,?)');$s->execute([$name,trim($_POST['location']??'')?:null,$count,trim($_POST['notes']??'')?:null,$memberId]);$id=(int)$pdo->lastInsertId();$b=$pdo->prepare('INSERT INTO house_breakers(panel_id,position_no,code) VALUES(?,?,?)');for($i=1;$i<=$count;$i++)$b->execute([$id,$i,'S'.$i]);log_activity($pdo,'house_panel_added','home_reminder',$id,$name);header('Location: /electrical-panels.php?panel='.$id);exit;}
 if($a==='save_breaker'){$id=(int)($_POST['id']??0);$pdo->prepare('UPDATE house_breakers SET code=?,label=?,description=?,amperage=?,circuit_type=?,module_span=? WHERE id=?')->execute([trim($_POST['code']??''),trim($_POST['label']??'')?:null,trim($_POST['description']??'')?:null,trim($_POST['amperage']??'')?:null,trim($_POST['circuit_type']??'')?:null,max(1,min(3,(int)($_POST['module_span']??1))),$id]);$message='Siguranța a fost actualizată.';}
 if($a==='delete_panel'){$id=(int)($_POST['id']??0);$pdo->prepare('DELETE FROM house_electrical_panels WHERE id=?')->execute([$id]);header('Location: /electrical-panels.php');exit;}
}catch(Throwable $e){$error=$e->getMessage();}}
$panelId=(int)($_GET['panel']??0);$panels=$pdo->query('SELECT * FROM house_electrical_panels ORDER BY id')->fetchAll();$panel=null;$breakers=[];if($panelId){$s=$pdo->prepare('SELECT * FROM house_electrical_panels WHERE id=?');$s->execute([$panelId]);$panel=$s->fetch();if($panel){$s=$pdo->prepare('SELECT * FROM house_breakers WHERE panel_id=? ORDER BY position_no');$s->execute([$panelId]);$breakers=$s->fetchAll();}}
$pageTitle=$panel?'Panou electric':'Panouri electrice';$active='more';$backUrl=$panel?'/electrical-panels.php':'/home.php';require __DIR__.'/includes/layout_top.php';?>
