<?php else:?>
<section class="hero-card subtle"><div><h2><?=e($panel['name'])?></h2><p><?=e($panel['location']?:'')?><?=$panel['notes']?' · '.e($panel['notes']):''?></p></div><a class="btn soft small" href="/electrical-panels.php">Toate panourile</a></section>
