<script>document.querySelectorAll('[data-edit-breaker]').forEach(b=>b.onclick=()=>{const f=document.getElementById('breakerForm'),m=document.getElementById('breakerSheet');['id','code','label','description','amperage'].forEach(k=>f.elements[k].value=b.dataset[k]||'');f.elements.circuit_type.value=b.dataset.type||'';f.elements.module_span.value=b.dataset.span||'1';m.classList.add('open');m.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')});</script>
